#!/usr/bin/env python3
"""Resolve an ML Kit Digital Ink pack name to its dl.google.com URL, download, verify, unzip.

The catalog ships inside the digital-ink-recognition AAR at assets/manifest.json;
every pack is a plain unauthenticated https://dl.google.com/handwriting/models/ URL.
"""
import hashlib, json, pathlib, sys, urllib.request, zipfile

ROOT = pathlib.Path(__file__).resolve().parent.parent
PACKS = {p["name"]: p for p in json.loads((ROOT / "manifest.json").read_text())["packs"]}


def fetch(name, dest=ROOT / "models"):
    pack = PACKS[name]
    url = pack["download_urls"][0]
    dest.mkdir(parents=True, exist_ok=True)
    zpath = dest / (name + ".zip")
    if not zpath.exists():
        print(f"GET {url}")
        urllib.request.urlretrieve(url, zpath)
    got = hashlib.sha1(zpath.read_bytes()).hexdigest()
    assert got == pack["sha1_checksum"], f"sha1 mismatch {got} != {pack['sha1_checksum']}"
    print(f"  ok sha1={got}  {zpath.stat().st_size/1e6:.2f} MB")
    with zipfile.ZipFile(zpath) as z:
        names = z.namelist()
        z.extractall(dest)
    for n in names:
        print(f"  -> {n}  ({(dest/n).stat().st_size/1e6:.2f} MB)")
    return [dest / n for n in names]


if __name__ == "__main__":
    for arg in sys.argv[1:]:
        if arg == "--list":
            for n in sorted(PACKS):
                print(n)
        else:
            fetch(arg)
